def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def first_pair(value):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            a, b = value[0], value[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return [a, b]
        return None

    def get_pos(obj, keys):
        for k in keys:
            v = obj.get(k) if hasattr(obj, "get") else None
            p = first_pair(v)
            if p is not None:
                return p
        return None

    def to_points(value):
        pts = []
        if isinstance(value, (list, tuple)):
            for item in value:
                p = first_pair(item)
                if p is not None:
                    pts.append(p)
        return pts

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection") if hasattr(observation, "get") else "resource_collection"
    sx_sy = get_pos(observation, ("self_position", "self_pos", "position", "agent_position")) or [0, 0]
    ox_oy = get_pos(observation, ("opponent_position", "enemy_position", "other_position")) or None

    grid_w = observation.get("grid_width", observation.get("width", 0)) if hasattr(observation, "get") else 0
    grid_h = observation.get("grid_height", observation.get("height", 0)) if hasattr(observation, "get") else 0
    if not isinstance(grid_w, int):
        grid_w = int(grid_w) if isinstance(grid_w, float) else 0
    if not isinstance(grid_h, int):
        grid_h = int(grid_h) if isinstance(grid_h, float) else 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer") if hasattr(observation, "get") else "pursuer"
        if role == "pursuer":
            if ox_oy is not None:
                return step_toward(sx_sy, ox_oy)
            return [0, 0]
        if grid_w > 0 and grid_h > 0:
            corners = [[0, 0], [0, grid_h - 1], [grid_w - 1, 0], [grid_w - 1, grid_h - 1]]
            if ox_oy is not None:
                target = corners[0]
                best = -1
                for c in corners:
                    score = manhattan(c, ox_oy)
                    if score > best:
                        best = score
                        target = c
                return step_toward(sx_sy, target)
            target = corners[(sx_sy[0] + sx_sy[1]) & 3]
            return step_toward(sx_sy, target)
        return [1, 1] if sx_sy[0] <= sx_sy[1] else [-1, -1]

    if env == "territory_control":
        targets = to_points(observation.get("unclaimed_cells", [])) if hasattr(observation, "get") else []
        if not targets:
            targets = to_points(observation.get("opponent_territory", [])) if hasattr(observation, "get") else []
        if not targets:
            targets = to_points(observation.get("frontier_cells", [])) if hasattr(observation, "get") else []
        if targets:
            best = targets[0]
            best_d = manhattan(sx_sy, best)
            for p in targets[1:]:
                d = manhattan(sx_sy, p)
                if d < best_d:
                    best_d = d
                    best = p
            if ox_oy is not None and manhattan(sx_sy, ox_oy) <= 2 and best_d > 0:
                away = step_away(sx_sy, ox_oy)
                if away != [0, 0]:
                    return away
            return step_toward(sx_sy, best)
        if ox_oy is not None:
            return step_away(sx_sy, ox_oy)
        return [0, 0]

    resources = to_points(observation.get("resources", [])) if hasattr(observation, "get") else []
    if not resources:
        resources = to_points(observation.get("resource_positions", [])) if hasattr(observation, "get") else []
    if resources:
        best = resources[0]
        best_d = manhattan(sx_sy, best)
        for p in resources[1:]:
            d = manhattan(sx_sy, p)
            if d < best_d:
                best_d = d
                best = p
        if ox_oy is not None and manhattan(sx_sy, ox_oy) <= 1:
            away = step_away(sx_sy, ox_oy)
            if away != [0, 0]:
                return away
        return step_toward(sx_sy, best)

    if ox_oy is not None:
        return step_away(sx_sy, ox_oy)
    return [0, 0]

